const identifyTaskDB=[{"s":"Que la norma la dictó quien podía, por el camino que correspondía.","type":"Validez"},{"s":"Que la norma está rigiendo hoy.","type":"Vigencia"},{"s":"Que la norma de verdad se cumple.","type":"Eficacia"},{"s":"El orden que decide cuál norma gana en un choque.","type":"Jerarquía"},{"s":"La consecuencia respaldada por la fuerza del Estado.","type":"Coacción"},{"s":"Que se acepte que quien manda tiene derecho a mandar.","type":"Legitimidad"},{"s":"Lo que la ley le permite expresamente a un funcionario.","type":"Facultad"},{"s":"Publicar la norma para que pueda obligar.","type":"Publicidad"},{"s":"«Siempre se ha hecho así», sin norma detrás.","type":"Costumbre"},{"s":"Quitarle vigencia a una norma con otra posterior.","type":"Derogación"}];
const classifyTaskDB=[{"w":"Un artículo de la Constitución","gen":"Naturaleza","n":"Norma, escalón más alto","g":"Es norma","t":"Gana cualquier choque"},{"w":"Un tratado en vigor","gen":"Naturaleza","n":"Norma, parte del derecho interno","g":"Es norma","t":"Prevalece sobre la ley"},{"w":"Una ley del Congreso","gen":"Naturaleza","n":"Norma con rango de ley","g":"Es norma","t":"Cede ante Constitución y tratado"},{"w":"Un reglamento del Ejecutivo","gen":"Naturaleza","n":"Norma que desarrolla una ley","g":"Es norma","t":"No puede pedir lo que la ley no pide"},{"w":"Un acuerdo de Secretaría","gen":"Naturaleza","n":"Norma de escalón bajo","g":"Es norma","t":"No recorta derechos de una ley"},{"w":"Una circular interna","gen":"Naturaleza","n":"Organiza al que ya está obligado","g":"No es norma","t":"No crea obligaciones nuevas"},{"w":"Un correo de la dirección","gen":"Naturaleza","n":"Comunicación, no fuente","g":"No es norma","t":"Sirve de prueba, no de fundamento"},{"w":"«Siempre se ha hecho así»","gen":"Naturaleza","n":"Costumbre de oficina","g":"No es norma","t":"Explica, no obliga"},{"w":"Un cartel en la ventanilla","gen":"Naturaleza","n":"Aviso sin rango","g":"No es norma","t":"Hay que pedir la norma que lo respalda"},{"w":"Un instructivo dicho de palabra","gen":"Naturaleza","n":"Ni escrito ni publicado","g":"No es norma","t":"Se pide por escrito"}];
const completeTaskDB=[{"s":"Una norma que nadie cumple sigue ___.","opts":["vigente","inválida","derogada"],"ans":"vigente"},{"s":"Si chocan la Constitución y una ley, se aplica la ___.","opts":["constitucional","más nueva","más corta"],"ans":"constitucional"},{"s":"Entre tratado vigente y ley, prevalece el ___.","opts":["tratado","reglamento","acuerdo"],"ans":"tratado"},{"s":"El funcionario solo puede lo que la ley le confiere ___.","opts":["expresamente","de palabra","por costumbre"],"ans":"expresamente"},{"s":"Sin ___ una norma no se le puede exigir a nadie.","opts":["publicación","reglamento","traducción"],"ans":"publicación"},{"s":"Que la dictara quien podía se llama ___.","opts":["validez","eficacia","vigencia"],"ans":"validez"},{"s":"Cuando un reglamento contradice su ley, se cae el ___.","opts":["reglamento","artículo","trámite"],"ans":"reglamento"},{"s":"La costumbre explica pero no crea la ___.","opts":["obligación","sanción","norma superior"],"ans":"obligación"}];
const explainQuestions=[{"q":"Explica la diferencia entre validez, vigencia y eficacia con un ejemplo de cada una.","ans":"Validez es que la norma nació bien: la dictó quien tenía la facultad, por el procedimiento que correspondía. Vigencia es que está rigiendo hoy, porque ya entró y nadie la derogó. Eficacia es que de verdad se cumple. No se implican: una norma puede ser válida y vigente y tener eficacia cero, y ese es el caso más frecuente. La confusión cara es dar por muerta una norma porque nadie la cumple, porque el día que alguien decida aplicarla se aplica igual."},{"q":"¿Por qué el artículo 321 es más útil para un ciudadano que casi cualquier otro?","ans":"Porque invierte la carga: el funcionario no puede hacer lo que quiera mientras no esté prohibido, solo puede lo que la ley le confiere expresamente, y lo que ejecute fuera de ella es nulo e implica responsabilidad. Con eso, ante un requisito raro, la pregunta deja de ser «convénzame» y pasa a ser «en qué norma dice usted que puede exigirme esto». Quien pregunta eso no está discutiendo, está pidiendo el fundamento que la Constitución ya exige."},{"q":"Un reglamento pide un papel que la ley no pide. ¿Qué se cae y por qué?","ans":"Se cae el reglamento en esa parte, no la ley. El reglamento existe para desarrollar la ley, no para ampliarla: si crea un requisito nuevo se salió de su escalón, y por el artículo 320 y por la lógica de la jerarquía, entre normas de distinto rango se aplica la superior. Lo importante en la práctica es que el reglamento se cae solo en el punto que excede, y el resto sigue rigiendo."},{"q":"¿Por qué la costumbre no sirve como respuesta en una ventanilla?","ans":"Porque la costumbre explica por qué la gente cumple algo, pero no lo convierte en exigible. «Siempre se ha hecho así» describe un hábito de oficina, no una fuente que obligue al ciudadano. Sirve para entender la eficacia de una norma, no para fundar una obligación nueva. La respuesta correcta es pedir la norma, por escrito, con su nombre y su artículo."},{"q":"¿Qué papel juega la publicación en La Gaceta y por qué no es un trámite menor?","ans":"Es la condición para poder obligar: una norma que no se publicó no se le puede exigir a nadie, porque el país no pudo conocerla. Viene de la idea más vieja que existe sobre la ley, la de escribirla en la plaza para que cualquiera la lea. En la práctica sirve de dos maneras: permite comprobar el texto exacto y su fecha, y desarma cualquier requisito que solo viva en un papel interno."},{"q":"Explica las tres razones por las que una norma se cumple y por qué ninguna basta sola.","ans":"Coacción: la consecuencia respaldada por la fuerza del Estado. Legitimidad: que se acepte que quien manda tiene derecho a mandar. Costumbre: que ya se venía haciendo. Ninguna basta sola. Solo con coacción no alcanzan los inspectores del mundo para sostener una norma que nadie acepta. Solo con legitimidad, el que decide incumplir no encuentra freno. Y la costumbre sostiene tanto lo bueno como lo que ya no tiene sentido."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Un solo contraejemplo basta para refutar una ley. → <span style="color:var(--jade);font-weight:700;">Falsacionismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

