const evalTFBank=[{"q":"Una norma que nadie cumple queda automáticamente derogada.","a":false},{"q":"Una norma puede ser válida y vigente y aun así no tener ninguna eficacia.","a":true},{"q":"La validez se refiere a que la norma la dictó quien tenía la facultad.","a":true},{"q":"Vigencia y eficacia significan lo mismo.","a":false},{"q":"Si una norma constitucional y una ley ordinaria son incompatibles, se aplica la constitucional.","a":true},{"q":"Un reglamento puede añadir requisitos que la ley que reglamenta no exige.","a":false},{"q":"Los tratados aprobados por el Congreso forman parte del derecho interno al entrar en vigor.","a":true},{"q":"En conflicto entre un tratado vigente y una ley, prevalece la ley nacional.","a":false},{"q":"Los servidores del Estado solo tienen las facultades que la ley les confiere expresamente.","a":true},{"q":"El particular necesita una norma que lo autorice para hacer algo que no está prohibido.","a":false},{"q":"Una circular interna crea obligaciones nuevas para el ciudadano.","a":false},{"q":"Una norma que no se publicó igual se le puede exigir a cualquiera.","a":false},{"q":"«Siempre se ha hecho así» es costumbre, y la costumbre no es un escalón de la pirámide.","a":true},{"q":"La coacción sola alcanza para que una norma se cumpla.","a":false},{"q":"Un acuerdo de Secretaría puede recortar un derecho reconocido por una ley del Congreso.","a":false}];
