function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Un director condiciona el uso de M.E.T.A.S en su centro a un permiso que solo aparece en una circular interna que él mismo firmó."},{"txt":"La Secretaría ofrece adoptar las misiones para todo un departamento, con un acuerdo que pide ceder los derechos del material. La Ley del Derecho de Autor reconoce esos derechos al autor."},{"txt":"Un reglamento educativo exige, para el material de apoyo, una aprobación previa que la ley que reglamenta no menciona en ninguna parte."},{"txt":"En la ventanilla del distrito le contestan que el trámite pide una constancia más, y que «siempre se ha hecho así». Nadie sabe decir de qué norma sale."},{"txt":"Un acuerdo departamental obliga a subir fotografías de los estudiantes a una plataforma. Hay un tratado sobre derechos de la niñez en vigor que protege su imagen."},{"txt":"Existe una norma vigente que obliga a registrar todo material educativo, y en la práctica no la cumple nadie ni nadie la exige desde hace años."},{"txt":"Le exigen a M.E.T.A.S un requisito que consta en un instructivo que nunca se publicó en La Gaceta, y del que solo hay una copia en la oficina."},{"txt":"Un funcionario nuevo interpreta el artículo 157 y decide que M.E.T.A.S es sistema formal, así que necesita autorización. El anterior opinaba lo contrario."}];
const critCaseQuestions=["1. ¿En qué escalón vive el papel que le están enseñando, y qué norma superior lo alcanza?","2. ¿Quién lo exige tiene la facultad expresa para exigirlo? ¿En qué norma consta?","3. ¿El problema es de validez, de vigencia o de eficacia? Nómbralo con esa palabra.","4. ¿Qué contestas por escrito, en dos líneas, y qué guardas del intercambio?"];
const critCaseGuides=["El escalón se nombra antes de discutir nada: Constitución, tratado en vigor, ley, reglamento, acuerdo, o papel que no es norma. Casi todos los problemas de esta casa vienen del último grupo, que no crea obligaciones nuevas para el ciudadano aunque venga en hoja membretada. Y cuando el papel sí es norma, la pregunta pasa a ser si contradice a alguna superior, porque entonces cede la de abajo y no la de arriba.","Aquí manda el artículo 321: el servidor del Estado no tiene más facultades que las que expresamente le confiere la ley, y lo que ejecute fuera de ella es nulo e implica responsabilidad. Enfrente está el artículo 70, que dice que al particular nadie lo obliga a lo que la ley no manda. La pregunta correcta nunca es «por qué no debería hacerlo yo», es «en qué norma dice usted que puede exigírmelo». No es una pelea: es pedir el fundamento que la Constitución ya exige.","Validez es que la norma nació bien; vigencia, que rige hoy; eficacia, que se cumple. Nombrar cuál falla cambia la respuesta entera. Si falla la validez, se ataca la norma. Si falla la vigencia, se demuestra con la fecha y el decreto que la derogó. Y si lo único que falla es la eficacia, la norma sigue viva: que nadie la aplique no es un permiso, es un riesgo dormido que despierta el día que alguien decida usarlo.","Se contesta corto, por escrito y citando: qué se pide, con qué norma y qué hecho. Y se guarda copia sellada de recibido con el nombre y el cargo de quien recibió. Lo que no queda por escrito no ocurrió, y el que tiene el expediente completo llega a la segunda reunión con una ventaja que no se compra. Si de la respuesta sale una contradicción entre dos normas, se abre su ficha en el Registro de Grietas antes de que se olvide."];

const critErrorBank=[{"txt":"\"Está escrito en hoja con sello y firma, así que hay que cumplirlo\".","g1":"El sello no da rango. Un instructivo sellado sigue siendo un papel que organiza a quien ya está obligado, y no crea obligaciones nuevas para el ciudadano.","g2":"Lo que hay que preguntar es en qué norma consta el requisito. Si no consta en ninguna, el artículo 321 lo desarma sin necesidad de discutir el fondo."},{"txt":"\"Esa ley ya no vale, hace años que nadie la cumple\".","g1":"Confunde eficacia con vigencia. Que nadie la cumpla no la deroga: sigue rigiendo y puede aplicarse cualquier día, normalmente el peor día.","g2":"Una norma solo pierde vigencia si otra posterior se la quita o si se declara inconstitucional. La costumbre de incumplir no deroga nada."},{"txt":"\"El reglamento es más específico, así que gana sobre la ley\".","g1":"El criterio de especialidad se usa entre normas del mismo rango. Entre rangos distintos manda la jerarquía, y el reglamento está por debajo de su ley.","g2":"Si el reglamento pide algo que la ley no pide, se salió de su escalón: cede el reglamento en esa parte, y solo en esa parte."},{"txt":"\"Como no hay ninguna norma que autorice lo que hacemos, no podemos hacerlo\".","g1":"Eso vale para el funcionario, no para el particular. El artículo 70 dice que nadie está obligado a lo que la ley no manda ni impedido de hacer lo que no prohíbe.","g2":"La pregunta correcta para un proyecto de la casa no es «qué norma me autoriza», es «qué norma me lo prohíbe». Cambia el trabajo entero de buscar."},{"txt":"\"Ese tratado no cuenta aquí, es internacional\".","g1":"Un tratado aprobado por el Congreso, una vez en vigor, forma parte del derecho interno. No es algo de fuera: rige aquí.","g2":"Y hay más: si choca con una ley, prevalece el tratado. Por eso conviene saber cuáles están en vigor antes de aceptar un requisito que los contradiga."},{"txt":"\"Lo dijo el funcionario, y él sabrá porque es su trabajo\".","g1":"El cargo no da la facultad: la da la ley, y expresamente. Un funcionario puede equivocarse de buena fe y su error no obliga a nadie.","g2":"Pedirlo por escrito no es desconfianza, es el paso que convierte una conversación en un hecho comprobable, y muchas veces el requisito desaparece en ese paso."}];

const critDecisionBank=["Le exigen un permiso que solo consta en una circular interna: ¿se cumple, se discute o se pide por escrito? ¿Con qué artículo se sostiene la respuesta?","Un acuerdo de Secretaría contradice una ley del Congreso: ¿cuál se aplica y qué se hace con el que cede?","Una norma vigente que nadie cumple alcanza a M.E.T.A.S: ¿se ignora como todos o se prepara la respuesta? ¿Qué cambia si un día la aplican?","Un tratado sobre derechos de la niñez choca con un acuerdo departamental que pide fotos de menores: ¿qué prevalece y cómo se dice sin pelear?","Un requisito viene en un instructivo que nunca se publicó: ¿es exigible? ¿Qué se pide antes de contestar?","Dos funcionarios interpretan distinto el mismo artículo: ¿de qué depende cuál interpretación se aplica, y qué se guarda por escrito?","Un reglamento pide más que su ley: ¿se cae el reglamento entero o solo una parte? ¿Qué se hace mientras tanto?","Le contestan «siempre se ha hecho así»: ¿qué se responde en una línea, sin discutir con la persona?"];
const critDecisionGuide='La decisión correcta en esta etapa sigue siempre el mismo orden: primero se nombra el dato que cruza la frontera y de dónde viene; después se escribe la comprobación como lista permitida y se pone del lado del servidor, que es el que el usuario no puede editar; después se decide qué pasa cuando la comprobación no se puede hacer, y ahí se falla cerrado, nunca en silencio; y al final se rompe la comprobación a propósito para ver que de verdad se pone roja. Si el fallo no se puede oír, todavía no está resuelto.';

const critCompareBank=[{"a":"Preguntar por escrito en qué norma consta el requisito.","b":"Discutir en la ventanilla que el requisito es injusto.","ga":"Caso A: pone la carga donde el artículo 321 la pone, deja constancia y muchas veces el requisito desaparece sin que nadie tenga que ceder en público.","gb":"Caso B: convierte un problema de fundamento en un problema de personas. Aunque se tenga razón, no queda registro y el funcionario tiene que defenderse."},{"a":"Comprobar la norma publicada y su fecha antes de contestar.","b":"Contestar de memoria porque uno ya leyó eso alguna vez.","ga":"Caso A: cuesta diez minutos y protege la credibilidad de todo lo demás que se va a decir en esa reunión.","gb":"Caso B: si el artículo cambió de número o lo reformaron, se pierde el punto y con él la confianza. Es el error que esta ruta prohíbe expresamente."},{"a":"Nombrar si el problema es de validez, de vigencia o de eficacia.","b":"Decir que «la norma está mal» y pedir que la cambien.","ga":"Caso A: cada uno tiene una respuesta distinta y una vía distinta. Nombrarlo bien es la mitad de la solución.","gb":"Caso B: mezcla tres problemas en uno y deja al otro sin nada concreto que responder. No abre ninguna puerta."},{"a":"Guardar copia sellada con el nombre y el cargo de quien recibió.","b":"Entregar el documento y confiar en que quedó registrado.","ga":"Caso A: convierte la entrega en un hecho probado, con fecha. Es lo que sostiene cualquier reclamo posterior.","gb":"Caso B: si mañana dicen que no llegó, no hay forma de demostrar lo contrario, y el plazo empieza a correr en contra."}];

const critCauseBank=[{"cause":"Se confunde eficacia con vigencia y se da por muerta una norma que nadie cumple.","guide":"El proyecto se acostumbra a ignorarla, y el día que alguien decide aplicarla no hay preparada ni una respuesta. Lo que era un riesgo dormido se vuelve un problema con plazo."},{"cause":"Se acepta un requisito porque venía en hoja sellada, sin preguntar en qué norma consta.","guide":"Se cumple un trámite que nadie podía exigir, y peor: queda el precedente de que aquí se cumple lo que se pida, así que la próxima vez se pedirá más."},{"cause":"Se cita un artículo de memoria en una reunión y el número está mal.","guide":"Se pierde el punto y, con él, la credibilidad de todo lo demás que se iba a decir. Esta es la razón exacta por la que la ruta prohíbe citar sin comprobar."},{"cause":"Se busca «qué norma me autoriza» en vez de «qué norma me lo prohíbe».","guide":"El proyecto se paraliza esperando un permiso que nadie tiene que dar, porque el artículo 70 ya reconoce que el particular puede lo que la ley no prohíbe."},{"cause":"Se discute el fondo con quien está en la ventanilla en vez de pedirlo por escrito.","guide":"La conversación no deja rastro, el requisito sigue vivo y ahora además hay una persona que tiene que quedar bien delante de su fila."},{"cause":"Se entrega un documento sin pedir copia sellada de recibido.","guide":"Si mañana dicen que no llegó, no hay cómo demostrarlo, y el plazo que uno creía cumplido nunca empezó a correr."}];
const critEffectBank=[{"effect":"El requisito raro desapareció sin que nadie tuviera que discutir.","guide":"Se pidió por escrito en qué norma constaba. Muchas veces no consta en ninguna, y la petición de fundamento resuelve sola lo que una discusión habría endurecido."},{"effect":"La reunión con la Secretaría se sostuvo sin ceder la autoría.","guide":"Se llegó sabiendo que un acuerdo de Secretaría no puede recortar un derecho reconocido por una ley del Congreso, y se llevó por escrito qué se acepta y con qué condición."},{"effect":"Cuando aplicaron aquella norma dormida, la respuesta ya estaba escrita.","guide":"Se había apuntado como riesgo de eficacia y no como norma muerta. Estaba en el Registro de Grietas con su ficha y su respuesta preparada."},{"effect":"El acuerdo departamental que pedía fotos de menores no se cumplió, y no pasó nada.","guide":"Se contestó citando el tratado en vigor, que forma parte del derecho interno y prevalece sobre la ley, y con más razón sobre un acuerdo."},{"effect":"Todo lo hablado en la dirección quedó probado.","guide":"Se entregó por escrito y se guardó copia sellada con el nombre y el cargo de quien recibió. Lo que no queda por escrito no ocurrió."},{"effect":"Nadie pudo decir que el proyecto necesitaba un permiso que no existía.","guide":"Se buscó qué norma lo prohíbe en vez de qué norma lo autoriza, y esa pregunta, que es la del artículo 70, dejó el terreno claro desde el principio."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 El papel sobre la mesa · Forma ${cf} · De dónde saca su fuerza la ley · Ruta de la Ley y sus Grietas`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. El papel sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿En qué escalón vive ese papel, quién lo exige tiene facultad expresa para exigirlo y qué falla: la validez, la vigencia o la eficacia? Explica qué contestas por escrito y qué guardas del intercambio.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos deja constancia y pone la carga donde la pone el artículo 321? 2. ¿Por qué no son la misma decisión?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0 a 20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 El papel sobre la mesa: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. El papel sobre la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿En qué escalón vive ese papel, quién lo exige tiene facultad expresa para exigirlo y qué falla: la validez, la vigencia o la eficacia? Explica qué contestas por escrito y qué guardas del intercambio.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos deja constancia y pone la carga donde la pone el artículo 321? 2. ¿Por qué no son la misma decisión?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>El papel sobre la mesa De dónde saca su fuerza la ley · Ruta de la Ley y sus Grietas · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · El papel sobre la mesa · De dónde saca su fuerza la ley · Ruta de la Ley y sus Grietas · Etapa 1 · Derecho y Ley</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: El papel sobre la mesa · De dónde saca su fuerza la ley · Ruta de la Ley y sus Grietas · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"📜","label":"La norma","text":"Una regla que <strong>obliga aunque no estés de acuerdo</strong>. <strong>Se reconoce:</strong> porque hay consecuencia y alguien con facultad para aplicarla. <strong>Se confunde:</strong> con el papel sellado que solo organiza una oficina. <strong>Aquí:</strong> casi todo lo que le exigen a M.E.T.A.S no es norma."},{"y":"2","icon":"✅","label":"La validez","text":"Que la norma <strong>nació bien</strong>. <strong>Se comprueba:</strong> viendo si la dictó quien podía y por el camino que correspondía. <strong>Se pierde:</strong> cuando un órgano dicta lo que no le toca. <strong>Aquí:</strong> un acuerdo que recorta una ley es inválido en esa parte."},{"y":"3","icon":"📅","label":"La vigencia","text":"Que la norma <strong>está rigiendo hoy</strong>. <strong>Se comprueba:</strong> con la fecha de publicación y con lo que la haya reformado o derogado. <strong>Se pierde:</strong> citando de memoria un artículo que ya cambió. <strong>Aquí:</strong> un artículo es un texto con fecha, no un texto."},{"y":"4","icon":"🎯","label":"La eficacia","text":"Que la norma <strong>de verdad se cumple</strong>. <strong>Se mide:</strong> en la calle, no en el papel. <strong>Se confunde:</strong> con la vigencia, y esa es la confusión más cara de la etapa. <strong>Aquí:</strong> la norma que nadie cumple es un riesgo dormido, no una norma muerta."},{"y":"5","icon":"🏛️","label":"La jerarquía","text":"El orden que decide <strong>cuál gana el choque</strong>. <strong>Regla:</strong> Constitución, tratado, ley, reglamento, acuerdo, y al final el papel que no es norma. <strong>Se pierde:</strong> creyendo que lo específico gana a lo superior. <strong>Aquí:</strong> el artículo 320 la sostiene entera."},{"y":"6","icon":"💪","label":"La coacción","text":"La consecuencia <strong>respaldada por la fuerza del Estado</strong>. <strong>Sirve para:</strong> que la norma no dependa de la buena voluntad. <strong>No basta sola:</strong> con legitimidad se cumple sin vigilancia, y sin ella no alcanzan los inspectores. <strong>Aquí:</strong> la costumbre es la tercera pata, y no es escalón."},{"y":"7","icon":"🏢","label":"La facultad","text":"Lo que la ley le permite <strong>expresamente</strong> a un funcionario, y nada más (art. 321). <strong>Enfrente:</strong> el artículo 70, que dice que al particular nadie lo obliga a lo que la ley no manda. <strong>Aquí:</strong> de esa asimetría sale la pregunta de ventanilla de esta misión."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(pideLaNorma){sfx(pideLaNorma?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(pideLaNorma){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">📝</span><span class="ms-text"><strong>Pediste la norma por escrito:</strong> nombre del requisito, artículo en que consta, y quién lo exige con su cargo. Sin levantar la voz y sin discutir el fondo.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">⚖️</span><span class="ms-text"><strong>Y el requisito se cayó solo:</strong> no constaba en ninguna norma, y el artículo 321 dice que el servidor del Estado no tiene más facultades que las que la ley le confiere expresamente. Nadie tuvo que ceder en público.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🧾</span><span class="ms-text"><strong>Cumpliste el requisito:</strong> se consiguió el papel, se pagó la copia y el trámite avanzó esa tarde. La sensación fue de problema resuelto.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📎</span><span class="ms-text"><strong>Y quedó el precedente:</strong> aquí se cumple lo que se pida. La próxima vez se pedirá uno más, y ahora será más difícil preguntar, porque la vez pasada no se preguntó.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"norma":{"nombre":"Qué es una norma","icon":"📜","estructura":{"title":"Qué es","info":"• Una regla que <strong>obliga aunque no estés de acuerdo</strong><br>• Detrás hay una consecuencia y alguien con facultad para aplicarla<br>• No es el tono lo que la distingue de un consejo, es eso"},"funcion":{"title":"Cómo se reconoce","info":"• Se pregunta <strong>quién la dictó y con qué facultad</strong><br>• Se busca dónde se publicó y desde cuándo rige<br>• Si nadie puede señalar norma ni fecha, es un papel, no una norma"},"enfermedades":{"title":"Dónde se cae","info":"• Al confundir hoja membretada y sello con rango normativo<br>• Al aceptar de palabra lo que nadie quiere poner por escrito<br>• Al tratar la costumbre de una oficina como si fuera fuente"},"cuidados":{"title":"En este proyecto","info":"• Casi todo lo que le exigen a M.E.T.A.S <strong>no es norma</strong><br>• Lo que sí lo es se puede nombrar: ley, decreto, artículo y fecha<br>• Lo demás se pide <strong>por escrito</strong>, y ahí suele desaparecer"}},"escalones":{"nombre":"Los escalones","icon":"🏛️","estructura":{"title":"Qué es","info":"• De arriba abajo: <strong>Constitución, tratado en vigor, ley, reglamento, acuerdo</strong><br>• Y al final, el papel que no es norma: circular, instructivo, correo<br>• Abajo no puede contradecir arriba"},"funcion":{"title":"Cómo se reconoce","info":"• Por <strong>quién la dictó</strong>: el Congreso hace leyes, el Ejecutivo reglamenta, la Secretaría acuerda<br>• El artículo 320 dice que entre Constitución y ley ordinaria se aplica la primera<br>• El artículo 18, que entre tratado y ley prevalece el tratado"},"enfermedades":{"title":"Dónde se cae","info":"• Creyendo que lo más específico gana siempre: eso vale <strong>entre iguales</strong><br>• Aceptando que un acuerdo recorte un derecho que reconoce una ley<br>• Discutiendo el fondo antes de saber en qué escalón está el papel"},"cuidados":{"title":"En este proyecto","info":"• El <strong>artículo 157</strong> es Constitución y por eso pesa tanto en el estatus de M.E.T.A.S<br>• La <strong>Ley Fundamental de Educación</strong> (Decreto 262-2011) es ley<br>• Lo que llega de un distrito suele ser acuerdo o circular: dos escalones más abajo"}},"vida":{"nombre":"La vida de una norma","icon":"📅","estructura":{"title":"Qué es","info":"• <strong>Validez:</strong> nació bien<br>• <strong>Vigencia:</strong> rige hoy<br>• <strong>Eficacia:</strong> de verdad se cumple<br>• Son tres cosas distintas y no se implican entre sí"},"funcion":{"title":"Cómo se reconoce","info":"• Validez: quién la dictó y por qué camino<br>• Vigencia: la publicación, la fecha de entrada y lo que la reformó<br>• Eficacia: lo que pasa de verdad en la ventanilla"},"enfermedades":{"title":"Dónde se cae","info":"• Dando por <strong>derogada</strong> una norma que solo tiene eficacia cero<br>• Citando un artículo que ya fue reformado y cambió de contenido<br>• Suponiendo que lo publicado hace años sigue igual hoy"},"cuidados":{"title":"En este proyecto","info":"• Toda cita lleva <strong>decreto de reforma y fecha de consulta</strong><br>• Una norma que nadie cumple se apunta como <strong>riesgo dormido</strong><br>• Lo que no se pudo comprobar se escribe como pendiente, a la vista"}},"facultad":{"nombre":"La facultad y la pregunta","icon":"🏢","estructura":{"title":"Qué es","info":"• <strong>Art. 321:</strong> el servidor del Estado solo tiene las facultades que la ley le confiere expresamente<br>• Y lo que ejecute fuera de la ley es nulo e implica responsabilidad<br>• <strong>Art. 70:</strong> al particular nadie lo obliga a lo que la ley no manda"},"funcion":{"title":"Cómo se reconoce","info":"• La pregunta de ventanilla: <strong>«¿en qué norma dice usted que puede exigirme esto?»</strong><br>• Se hace sin subir la voz y por escrito si se puede<br>• No es una pelea: es pedir el fundamento que la Constitución ya exige"},"enfermedades":{"title":"Dónde se cae","info":"• Buscando <strong>qué norma me autoriza</strong> cuando la pregunta es qué norma me lo prohíbe<br>• Suponiendo que el cargo da la facultad: la da la ley<br>• Discutiendo con la persona en vez de pedir el fundamento"},"cuidados":{"title":"En este proyecto","info":"• Toda exigencia se pide <strong>por escrito</strong>, con nombre y cargo de quien la hace<br>• De todo lo entregado se guarda <strong>copia sellada de recibido</strong><br>• Si aparece una contradicción, se abre su ficha en el <strong>Registro de Grietas</strong>"}}};
let labParte='norma',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente gestor en formación!','¡Sabes por dónde se mueve esto!','¡Estratega institucional!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='⚖️ ¡'+name+' completó la Etapa 1 de la Ruta de la Ley y sus Grietas (De dónde saca su fuerza la ley)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

